using System.Text;
using System.Text.Json;

namespace Ivy.BindingGenerator;

// A real metadata-driven emitter. Unsupported layouts are listed, never emitted as stubs.
public static class TypedAccessGenerator
{
    public static readonly string[] Profile = ["Terraria.Entity", "Terraria.Main", "Terraria.Player", "Terraria.Item", "Terraria.NPC", "Terraria.Projectile"];
    private static readonly Dictionary<string, string> scalars = new()
    {
        ["System.Boolean"]="bool", ["System.Byte"]="byte", ["System.SByte"]="sbyte", ["System.Char"]="char",
        ["System.Int16"]="short", ["System.UInt16"]="ushort", ["System.Int32"]="int", ["System.UInt32"]="uint",
        ["System.Int64"]="long", ["System.UInt64"]="ulong", ["System.Single"]="float", ["System.Double"]="double"
    };
    public sealed record Result(string Source, int Types, int Fields, int Methods, int Properties, string[] Omitted) { public Dictionary<string,int> Families { get; init; } = []; }
    public static Result Generate(ApiCatalog catalog)
    {
        var types = catalog.Assemblies.SelectMany(a=>a.Types).Where(t=>Profile.Contains(t.Name) && t.Kind=="class" && t.GenericArity==0).OrderBy(t=>t.Name,StringComparer.Ordinal).ToArray();
        if (types.Length != Profile.Length) throw new InvalidDataException("Perfil exige Entity, Main, Player, Item, NPC e Projectile.");
        var b = new StringBuilder("// <auto-generated/> TypedAccessGenerator; do not edit.\n#nullable enable\nusing Ivy.Runtime;\nnamespace Terraria;\n\n");
        var familyCounts=new Dictionary<string,int>{{"scalarFields",0},{"referenceFields",0},{"arrayFields",0},{"vector2Fields",0},{"rectangleFields",0},{"colorFields",0}};
        var omissions = new List<string>(); int fields=0, methods=0, properties=0;
        bool Supported(string type) => scalars.ContainsKey(type) || Profile.Contains(type);
        bool Vector(string type)=>type=="Microsoft.Xna.Framework.Vector2";
        bool Struct(string type)=>Vector(type)||type is "Microsoft.Xna.Framework.Rectangle" or "Microsoft.Xna.Framework.Graphics.Color";
        bool FieldType(string type)=>Supported(type)||Struct(type)||type.EndsWith("[]",StringComparison.Ordinal)&&(Supported(type[..^2])||Struct(type[..^2]));
        string Cs(string type)=>type=="System.Void"?"void":Struct(type)?"global::"+(type=="Microsoft.Xna.Framework.Graphics.Color"?"Microsoft.Xna.Framework.Color":type):type.EndsWith("[]",StringComparison.Ordinal)?"global::Ivy.Runtime.NativeArray<"+Cs(type[..^2])+">?":scalars.GetValueOrDefault(type)??"global::"+type+"?";
        string Q(string s) => JsonSerializer.Serialize(s);
        string Value(string type,string expression)=>Struct(type)?expression+(Vector(type)?".Vector()":type.EndsWith("Rectangle",StringComparison.Ordinal)?".Rectangle()":".Color()"):type.EndsWith("[]",StringComparison.Ordinal)?expression+".Reference is { } arrayIdentity ? new global::Ivy.Runtime.NativeArray<"+Cs(type[..^2])+">(arrayIdentity, "+Q(type[..^2])+", static element => "+Value(type[..^2],"element")+", static element => NativeValue.From(element)) : null":scalars.TryGetValue(type,out var scalar) ? type switch {
            "System.Boolean" => expression+".Bits != 0", "System.Single" => "global::System.BitConverter.UInt32BitsToSingle((uint)"+expression+".Bits)",
            "System.Double" => "global::System.BitConverter.UInt64BitsToDouble("+expression+".Bits)", _ => "unchecked(("+scalar+")"+expression+".Bits)"
        } : expression+".Reference is { } identity ? new global::"+type+"(identity) : null";
        bool Identifier(string s) => s.Length>0 && (char.IsLetter(s[0]) || s[0]=='_') && s.All(c=>char.IsLetterOrDigit(c)||c=='_');
        foreach (var t in types)
        {
            var shortName=t.Name.Split('.').Last(); var existing=t.Name is "Terraria.Main" or "Terraria.Player";
            var parent=types.Any(x=>x.Name==t.BaseType) ? t.BaseType! : "Ivy.Runtime.NativeObject";
            b.Append("public partial class ").Append(shortName).Append(existing ? "\n{\n" : " : global::"+parent+"\n{\n    internal "+shortName+"(object identity) : base(identity) { }\n");
            var reserved = new HashSet<string>(["Identity",shortName,"__ivyValue"]);
            if (t.Name=="Terraria.Main") reserved.UnionWith(["LocalPlayer","menuMode","myPlayer","DoUpdateInWorld"]);
            if (t.Name=="Terraria.Player") reserved.UnionWith(["statLife","statLifeMax2"]);
            string Descriptor(string name,string value,bool isStatic,bool field,bool writable,string[] args,int token)
            {
                var id="__ivy_"+(field?"f":"m")+token.ToString("X8");
                b.Append("    private static readonly NativeMember ").Append(id).Append(" = new(").Append(Q(t.Assembly)).Append(", ").Append(Q(t.Name)).Append(", ").Append(Q(name)).Append(", ").Append(Q(value)).Append(", ").Append(isStatic?"true":"false").Append(", ").Append(field?"true":"false").Append(", ").Append(writable?"true":"false");
                foreach(var p in args)b.Append(", ").Append(Q(p)); b.Append(");\n");return id;
            }
            string Target(bool st)=>st?"null":"this.Identity";
            foreach(var f in t.Fields.OrderBy(x=>x.Token))
            {
                if(reserved.Contains(f.Name)) continue;
                if(!FieldType(f.Type)||!Identifier(f.Name)||f.IsLiteral) {omissions.Add(t.Name+"."+f.Name+": unsupported field type/literal/name");continue;}
                reserved.Add(f.Name); var write=!f.IsReadOnly;
                var id=Descriptor(f.Name,f.Type,f.IsStatic,true,write,[],f.Token);
                b.Append("    public ").Append(f.IsStatic?"static ":"").Append(Cs(f.Type)).Append(" @").Append(f.Name).Append("\n    {\n        get { var __ivyValue = NativeAccess.Backend.Read(").Append(id).Append(", ").Append(Target(f.IsStatic)).Append("); return ").Append(Value(f.Type,"__ivyValue")).Append("; }\n");
                if(write)b.Append("        set => NativeAccess.Backend.Write(").Append(id).Append(", ").Append(Target(f.IsStatic)).Append(", NativeValue.From(value));\n");
                b.Append("    }\n"); fields++;
                familyCounts[f.Type.EndsWith("[]",StringComparison.Ordinal)?"arrayFields":Vector(f.Type)?"vector2Fields":f.Type=="Microsoft.Xna.Framework.Rectangle"?"rectangleFields":f.Type=="Microsoft.Xna.Framework.Graphics.Color"?"colorFields":scalars.ContainsKey(f.Type)?"scalarFields":"referenceFields"]++;
            }
            var accessorTokens=t.Properties.SelectMany(p=>new[]{p.GetterToken,p.SetterToken}).Where(x=>x.HasValue).Select(x=>x!.Value).ToHashSet();
            var accessorMethods=new HashSet<int>();
            foreach(var p in t.Properties)
            {
                if(reserved.Contains(p.Name))continue;
                var get=t.Methods.SingleOrDefault(m=>m.Token==p.GetterToken);var set=t.Methods.SingleOrDefault(m=>m.Token==p.SetterToken);
                if(get is null||!Supported(p.Type)||p.IndexTypes.Length!=0||!Identifier(p.Name)||get.GenericArity!=0) {omissions.Add(t.Name+"."+p.Name+": unsupported property");continue;}
                reserved.Add(p.Name); accessorMethods.Add(get.Token);
                var id=Descriptor(get.Name,p.Type,get.IsStatic,false,false,[],get.Token);
                var setter=set is not null&&set.IsStatic==get.IsStatic&&set.Parameters.Length==1&&set.Parameters[0].Type==p.Type;
                string? sid=null;if(setter){sid=Descriptor(set!.Name,"System.Void",set.IsStatic,false,false,[p.Type],set.Token);accessorMethods.Add(set.Token);}
                b.Append("    public ").Append(get.IsStatic?"static ":"").Append(Cs(p.Type)).Append(" @").Append(p.Name).Append("\n    {\n        get { var __ivyValue = NativeAccess.Backend.Invoke(").Append(id).Append(", ").Append(Target(get.IsStatic)).Append(", []); return ").Append(Value(p.Type,"__ivyValue")).Append("; }\n");
                if(setter)b.Append("        set => NativeAccess.Backend.Invoke(").Append(sid).Append(", ").Append(Target(get.IsStatic)).Append(", [NativeValue.From(value)]);\n");
                b.Append("    }\n"); properties++;
            }
            var signatures=new HashSet<string>();
            foreach(var m in t.Methods.OrderBy(x=>x.Token))
            {
                if(accessorTokens.Contains(m.Token)||accessorMethods.Contains(m.Token)||reserved.Contains(m.Name))continue;
                var sig=m.Name+"("+string.Join(",",m.Parameters.Select(p=>p.Type))+")";
                if(!Identifier(m.Name)||m.GenericArity!=0||!Supported(m.ReturnType)&&m.ReturnType!="System.Void"||m.Parameters.Length>8||m.Parameters.Any(p=>!Supported(p.Type))||m.ReviewReasons.Any(r=>r is "abstract-no-native-body" or "extern-or-internal-call" or "varargs")||!signatures.Add(sig))
                {omissions.Add(t.Name+"."+sig+": unsupported signature");continue;}
                string Arg(int i) => m.Parameters.All(p=>Identifier(p.Name)&&p.Name!="__ivyValue") && m.Parameters.Select(p=>p.Name).Distinct().Count()==m.Parameters.Length ? "@"+m.Parameters[i].Name : "arg"+i;
                string? Default(ParameterContract p)
                {
                    if(!p.Optional)return null;
                    if(p.Default is null)return Profile.Contains(p.Type)?"null":null;
                    var split=p.Default.IndexOf(':');if(split<0)return null;
                    var raw=p.Default[(split+1)..];
                    return p.Type switch {
                        "System.Boolean" => raw.ToLowerInvariant(),
                        "System.Char" => raw.Length==1 ? "'\\u"+((int)raw[0]).ToString("X4")+"'" : null,
                        "System.Single" => raw is "NaN" or "Infinity" or "-Infinity" ? "float."+(raw=="-Infinity"?"NegativeInfinity":raw=="Infinity"?"PositiveInfinity":"NaN") : raw+"f",
                        "System.Double" => raw is "NaN" or "Infinity" or "-Infinity" ? "double."+(raw=="-Infinity"?"NegativeInfinity":raw=="Infinity"?"PositiveInfinity":"NaN") : raw+"d",
                        "System.Int64" => raw+"L", "System.UInt64" => raw+"UL", "System.UInt32" => raw+"U",
                        _ => scalars.ContainsKey(p.Type)?raw:raw=="null"?"null":null
                    };
                }
                string Parameter(int i) => Cs(m.Parameters[i].Type)+" "+Arg(i)+(m.Parameters.Skip(i).All(p=>Default(p) is not null)?" = "+Default(m.Parameters[i]):"");
                var id=Descriptor(m.Name,m.ReturnType,m.IsStatic,false,false,m.Parameters.Select(p=>p.Type).ToArray(),m.Token);
                b.Append("    public ").Append(m.IsStatic?"static ":"").Append(Cs(m.ReturnType)).Append(" @").Append(m.Name).Append('(').Append(string.Join(", ",m.Parameters.Select((p,i)=>Parameter(i)))).Append(")\n    {\n        ");
                if(m.ReturnType!="System.Void")b.Append("var __ivyValue = ");
                b.Append("NativeAccess.Backend.Invoke(").Append(id).Append(", ").Append(Target(m.IsStatic)).Append(", [").Append(string.Join(", ",m.Parameters.Select((p,i)=>"NativeValue.From("+Arg(i)+")"))).Append("]);\n");
                if(m.ReturnType!="System.Void")b.Append("        return ").Append(Value(m.ReturnType,"__ivyValue")).Append(";\n");
                b.Append("    }\n");methods++;
            }
            b.Append("}\n\n");
        }
        using(var stream=typeof(TypedAccessGenerator).Assembly.GetManifestResourceStream("Ivy.HookFamilies.json")!)
        using(var profile=JsonDocument.Parse(stream))
        foreach(var h in profile.RootElement.EnumerateArray())
        {
            var type=h.GetProperty("type").GetString();var method=h.GetProperty("method").GetString();
            if(!types.Single(t=>t.Name==type).Methods.Any(m=>m.Name==method&&!m.IsStatic&&m.GenericArity==0&&m.ReturnType==h.GetProperty("result").GetString()&&m.Parameters.Select(p=>p.Type).SequenceEqual(h.GetProperty("parameters").EnumerateArray().Select(p=>p.GetString()))))throw new InvalidDataException("Hook de família incompatível: "+method);
        }
        var heal = types.Single(t=>t.Name=="Terraria.Player").Methods.SingleOrDefault(m=>m.Name=="HealEffect" && !m.IsStatic && m.GenericArity==0 && m.ReturnType=="System.Void" && m.Parameters.Select(p=>p.Type).SequenceEqual(new[]{"System.Int32","System.Boolean"}));
        if(heal is null)throw new InvalidDataException("Assinatura incompatível: Player.HealEffect(int,bool).");
        b.Append("public static partial class On_Player\n{\n    public delegate void orig_HealEffect(Player self, int healAmount, bool broadcast);\n    public delegate void hook_HealEffect(orig_HealEffect orig, Player self, int healAmount, bool broadcast);\n    public static event hook_HealEffect HealEffect\n    {\n        add => HealHooks.Add(value);\n        remove => HealHooks.Remove(value);\n    }\n}\n");
        return new(b.ToString(),types.Length,fields,methods,properties,omissions.Order(StringComparer.Ordinal).ToArray()) { Families=familyCounts };
    }
}
